QUESTION_WORDS = {
  "en": ["where", "which", "what", "how", "tell", "suggest", "recommend"],
  "hi": ["कहाँ", "कौन", "क्या", "कैसे", "बताएं", "सुझाव"],
  "te": ["ఎక్కడ", "ఏది", "ఏమిటి", "ఎలా", "చెప్పండి", "సూచించండి"],
  "ta": ["எங்கே", "எது", "என்ன", "எப்படி", "சொல்லுங்கள்", "பரிந்துரை"],
  "kn": ["ಎಲ್ಲಿ", "ಯಾವುದು", "ಏನು", "ಹೇಗೆ", "ಹೇಳಿ", "ಸೂಚಿಸಿ"],
  "mr": ["कुठे", "कोणते", "काय", "कसे", "सांगा", "सुचवा"],
}


def get_bot_response(message, lang="en"):
    # Fall back to English knowledge base / fallback text if an
    # unsupported language code is passed in.
    if lang not in KNOWLEDGE_BASE:
        lang = "en"

    message_lower = message.lower()
    kb = KNOWLEDGE_BASE[lang]

    # Keyword matching is always done in English, since keywords
    # (place/topic names) are consistent regardless of reply language.
    en_kb = KNOWLEDGE_BASE["en"]
    for keyword in en_kb.keys():
        if keyword in message_lower:
            return kb.get(keyword, en_kb[keyword])

    question_words = QUESTION_WORDS.get(lang, QUESTION_WORDS["en"])
    if any(w in message_lower for w in question_words) or \
       any(w in message_lower for w in QUESTION_WORDS["en"]):
        return FALLBACK_QUESTION.get(lang, FALLBACK_QUESTION["en"])

    return FALLBACK_DEFAULT.get(lang, FALLBACK_DEFAULT["en"])


@chatbot_bp.route('/chat', methods=['POST'])
def chat():
    data = request.get_json()
    if not data or 'message' not in data:
        return jsonify({"success": False, "message": "No message provided"}), 400
    user_message = data['message']
    lang = data.get('lang', 'en')
    bot_response = get_bot_response(user_message, lang)
    return jsonify({
        "success": True,
        "userMessage": user_message,
        "botResponse": bot_response
    })